// src/common/collections.rs:87-101 (list endpoint backend)
pub async fn do_list_collections(toc: &TableOfContent, auth: &Auth) -> Result<CollectionsResponse, StorageError> {
    let collections = toc
        .all_collections(auth.access("list_collections"))
        .await
        .into_iter()
        .map(|pass| CollectionDescription { name: pass.name().to_string() })
        .collect_vec();
    Ok(CollectionsResponse { collections })
}

